// isBase64 — validate standard / URL-safe Base64 (bug-fix starter)
// Source: src/lib/isBase64.js (validator.js 13.15.35)
// assertString / merge match the repo.

function assertString(input) {
  if (typeof input !== 'string') {
    const invalidType = input === null ? 'null' : typeof input;
    throw new TypeError(`Expected a string but received a ${invalidType}`);
  }
}

function merge(obj = {}, defaults) {
  if (typeof obj !== 'object' || obj === null) {
    obj = {};
  }
  for (const key in defaults) {
    if (typeof obj[key] === 'undefined') {
      obj[key] = defaults[key];
    }
  }
  return obj;
}

const base64WithPadding = /^[A-Za-z0-9+/]+={0,2}$/;
const base64WithoutPadding = /^[A-Za-z0-9+/]+$/;
const base64UrlWithPadding = /^[A-Za-z0-9_-]+={0,2}$/;
const base64UrlWithoutPadding = /^[A-Za-z0-9_-]+$/;

function isBase64(str, options) {
  assertString(str);
  options = merge(options, { urlSafe: false, padding: true });

  if (str === '') return true;

  if (options.padding && str.length % 4 !== 0) return false;

  let regex;
  if (options.urlSafe) {
    regex = options.padding ? base64UrlWithPadding : base64UrlWithoutPadding;
  } else {
    regex = options.padding ? base64WithPadding : base64WithoutPadding;
  }

  return (!options.padding || str.length % 4 === 0) && regex.test(str);
}

